def run_algorithm(grid_h, grid_w, positions, bg=5):
    output = [[bg for _ in range(grid_w)] for _ in range(grid_h)]
    for r in range(grid_h):
        for c in range(grid_w):
            if grid_h > 0 and r < len(grid_actual) and grid_actual[r][c] == 3:
                output[r][c] = 3

    # Keep track of what's filled to avoid re-filling
    filled = set()

    for r, c, v in sorted(positions):
        # shift left
        new_c = c - 1
        if 0 <= new_c < grid_w:
            if (r, new_c) not in filled:
                output[r][new_c] = v
                filled.add((r, new_c))
                # cascade
                rr, cc = r + 1, new_c - 1
                while 0 <= rr < grid_h and 0 <= cc < grid_w:
                    if (rr, cc) not in filled:
                        output[rr][cc] = v
                        filled.add((rr, cc))
                    else:
                        break
                    rr += 1
                    cc -= 1
    return output

