# Fix: cascade fills ALL positions in the cascade chain, source included
# Values are written (not destroyed)

def full_cascade(grid_h, grid_w, positions, bg=1):
    output = [[bg for _ in range(grid_w)] for _ in range(grid_h)]
    for r, c, v in [(3,3,3), (4,2,3), (5,2,3)]:
        output[r][c] = 3

    filled = set()

    def cascade_from(r, c, v):
        rr, cc = r, c  # Include source
        while 0 <= rr < grid_h and 0 <= cc < grid_w:
            if (rr, cc) not in filled:
                output[rr][cc] = v
                filled.add((rr, cc))
                rr += 1
                cc -= 1
            else:
                break

    for r, c, v in positions:
        print(f"Cascade {v} from ({r},{c})")
        cascade_from(r, c, v)

    return output

